<?php
declare(strict_types=1);
namespace App\PackageModules\Products;
use App\Platform\Contracts\PlatformRequestInterface;
use App\Platform\Package\AbstractPackageModule;
use App\Platform\Package\PlatformResponse;
use App\Platform\PlatformContext;
final class ProductsModule extends AbstractPackageModule
{
 public function name(): string{return 'products';} public function label(): string{return 'Товары';} public function priority(): int{return 66;}
 public function adminNav(): array{return [['group'=>'Коммерция','path'=>'/admin/products','label'=>'Товары','permission'=>'commerce.manage','icon'=>'shopping-cart'],['group'=>'Коммерция','path'=>'/admin/products-templates','label'=>'Шаблоны витрины','permission'=>'commerce.manage','icon'=>'layout']];}
 public function blocks(): array{return [['type'=>'products-grid','label'=>'Сетка товаров','category'=>'commerce','settings_schema'=>[['key'=>'title','label'=>'Заголовок','type'=>'text'],['key'=>'subtitle','label'=>'Подзаголовок','type'=>'textarea'],['key'=>'limit','label'=>'Лимит','type'=>'number'],['key'=>'columns','label'=>'Колонки','type'=>'number']]]];}
 public function bootPlatform(PlatformContext $ctx): void { parent::bootPlatform($ctx); $ctx->capabilities()->require('api.routes'); $db=$ctx->database(); $http=$ctx->http(); $perms=$ctx->permissions(); $svc=static fn()=>new ProductService($db);
  $ctx->catalog()->registerBackend(static fn()=> $db->all('SELECT * FROM products WHERE is_visible=1 AND price>0 AND deleted_at IS NULL ORDER BY sort_order,id'),static fn(int $id)=>$db->one('SELECT id,sku,title,price,currency,stock,is_purchasable,is_visible FROM products WHERE id=? AND is_visible=1 AND is_purchasable=1 AND deleted_at IS NULL',[$id]),static fn(string $sku)=>$db->one('SELECT id,sku,title,price,currency,stock,is_purchasable,is_visible FROM products WHERE sku=? AND is_visible=1 AND is_purchasable=1 AND deleted_at IS NULL',[trim($sku)]),static function(int $id,int $quantity)use($db):bool{$row=$db->one('SELECT stock FROM products WHERE id=? AND stock IS NOT NULL AND stock>=? AND deleted_at IS NULL',[$id,$quantity]);if(!$row)return false;$db->run('UPDATE products SET stock=stock-? WHERE id=?',[$quantity,$id]);return true;});
  $protected=[$http->authMiddleware(),$http->permissionMiddleware()];
  $http->get('/admin/products',static function(PlatformRequestInterface $r)use($svc,$perms){$perms->require($r->user()??[],'commerce.manage');PlatformResponse::json(['data'=>$svc()->list()]);},$protected);
  $http->post('/admin/products',static function(PlatformRequestInterface $r)use($svc,$perms){$perms->require($r->user()??[],'commerce.manage');try{PlatformResponse::json(['data'=>$svc()->create($r->body())],201);}catch(\InvalidArgumentException $e){PlatformResponse::error($e->getMessage(),422);}},$protected);
  $http->get('/admin/products/{id}',static function(PlatformRequestInterface $r,string $id)use($svc,$perms){$perms->require($r->user()??[],'commerce.manage');$row=$svc()->get((int)$id);if(!$row)PlatformResponse::error('Not found',404);PlatformResponse::json(['data'=>$row]);},$protected);
  $http->put('/admin/products/{id}',static function(PlatformRequestInterface $r,string $id)use($svc,$perms){$perms->require($r->user()??[],'commerce.manage');try{PlatformResponse::json(['data'=>$svc()->update((int)$id,$r->body())]);}catch(\OutOfBoundsException){PlatformResponse::error('Not found',404);}catch(\InvalidArgumentException $e){PlatformResponse::error($e->getMessage(),422);}},$protected);
  $http->delete('/admin/products/{id}',static function(PlatformRequestInterface $r,string $id)use($svc,$perms){$perms->require($r->user()??[],'commerce.manage');try{$svc()->delete((int)$id);}catch(\OutOfBoundsException){PlatformResponse::error('Not found',404);}PlatformResponse::json(['message'=>'Moved to trash','data'=>['id'=>(int)$id,'resource'=>'products','mode'=>'trash']]);},$protected);

  $http->get('/admin/products-meta/templates',static function(PlatformRequestInterface $r)use($ctx,$perms){$perms->require($r->user()??[],'commerce.manage');$active=(string)$ctx->settings()->get('storefront_template',ProductTemplates::defaultId());PlatformResponse::json(['data'=>['active'=>$active,'page_slug'=>ProductTemplates::pageSlug($active),'templates'=>ProductTemplates::catalog(),'form_fields'=>ProductTemplates::formFields($active)]]);},$protected);
  $http->put('/admin/products-meta/templates',static function(PlatformRequestInterface $r)use($ctx,$perms){$perms->require($r->user()??[],'commerce.manage');$body=$r->body();$id=trim((string)($body['storefront_template']??''));if(!in_array($id,ProductTemplates::ids(),true))PlatformResponse::error('Неизвестный шаблон',422);$ctx->settings()->set('storefront_template',$id);PlatformResponse::json(['success'=>true,'data'=>['active'=>$id,'page_slug'=>ProductTemplates::pageSlug($id),'templates'=>ProductTemplates::catalog(),'form_fields'=>ProductTemplates::formFields($id)]]);},$protected);
  $http->get('/products/config',static function()use($ctx){$active=(string)$ctx->settings()->get('storefront_template',ProductTemplates::defaultId());PlatformResponse::json(['data'=>['storefront_template'=>$active,'page_slug'=>ProductTemplates::pageSlug($active),'templates'=>array_map(static fn(array $t)=>['id'=>$t['id'],'title'=>$t['title'],'page_slug'=>ProductTemplates::pageSlug((string)$t['id'])],ProductTemplates::catalog())]]);});
  $http->get('/products',static function(PlatformRequestInterface $r)use($db){$result=(new ProductCatalog($db))->search($r->query());PlatformResponse::json(['data'=>$result['items'],'total'=>$result['total'],'facets'=>$result['facets'],'meta'=>$result['meta']]);});
  $http->get('/products/facets',static function()use($db){$result=(new ProductCatalog($db))->search(['limit'=>1]);PlatformResponse::json(['data'=>$result['facets']]);});
  $http->get('/products/{slug}',static function(PlatformRequestInterface $r,string $slug)use($db){$row=$db->one('SELECT * FROM products WHERE slug=? AND is_visible=1 AND deleted_at IS NULL',[$slug]);if(!$row)PlatformResponse::error('Not found',404);PlatformResponse::json(['data'=>$row]);});
 }
}